```cpp
    std::vector<Node> nodes;
    nodes.reserve(rt.number_of_vertices());

    for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
        Node node;
        const auto& point = vit->point();
        node.position = {point.x(), point.y(), point.z()};

        // Extract velocity (assuming it's stored in the vertex handle or via a trait)
        // If not directly available, default to zero or use a placeholder.
        // This is a critical assumption; adjust if the codebase stores velocity elsewhere.
        node.velocity = {0.0, 0.0, 0.0};

        // Extract mass (weight in Regular_triangulation_3)
        node.mass = CGAL::to_double(vit->weight());

        // Classify node type based on incident edges and threshold
        int edge_count = 0;
        auto circ = rt.incident_edges(vit);
        auto done = circ;
        if (circ != nullptr) {
            do {
                if (!rt.is_infinite(*circ)) {
                    edge_count++;
                }
            } while (++circ != done);
        }

        if (edge_count == 0) {
            node.type = Node::VOID;
        } else if (edge_count <= 2) {
            node.type = Node::FILAMENT;
        } else if (edge_count == 3) {
            node.type = Node::WALL;
        } else if (edge_count == 4) {
            node.type = Node::KURTOPARABOLIC;
        } else {
            // Check if edges are shorter than threshold (cluster condition)
            bool is_cluster = true;
            circ = rt.incident_edges(vit);
            done = circ;
            if (circ != nullptr) {
                do {
                    if (!rt.is_infinite(*circ)) {
                        auto edge = *circ;
                        auto v1 = edge.first->vertex(rt.vertex_triple_index(edge, 0));
                        auto v2 = edge.first->vertex(rt.vertex_triple_index(edge, 1));
                        if (v1 != vit && v2 != vit) {
                            double distance = CGAL::sqrt(CGAL::to_double(
                                CGAL::squared_distance(vit->point(), v1 == vit ? v2->point() : v1->point())));
                            if (distance > threshold) {
                                is_cluster = false;
                                break;
                            }
                        }
                    }
                } while (++circ != done);
            }
            node.type = is_cluster ? Node::CLUSTER : Node::UNDEFINED_NODE_TYPE;
        }

        nodes.push_back(node);
    }

    return nodes;
